  translation -2.5 -2 1
  rotation 0 1 0 0.8
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 0 0 0
        emissiveColor 1 1 1
      }
    }
    geometry DEF XC Text {
      string "Tilted"
      fontStyle DEF FC ScreenFontStyle {
        pointSize 18
      }
    }
  }
}

DEF K KeySensor { }

DEF R Script {
  inputOnly      SFString on_key
  inputOutput    SFString log ""
  initializeOnly SFNode   ta USE TA
  initializeOnly SFNode   fa USE FA
